-- ======================================================================
-- GEM.VAP PILOTAGE — Import des relevés bancaires PDF 2023 (12 mois)
-- Source : 12 relevés PDF Crédit Agricole, vérifiés (écart 0,00 € sur chaque mois)
-- 4018 opérations, SANS catégorisation automatique (dictionnaire remis à zéro)
-- Toutes les lignes arrivent en état "à catégoriser"
-- IMPORTANT : exécutez d'abord 15_exercice_2022_2023.sql
-- Le nom de fichier enregistré (ex: 01.2023.pdf) correspond à celui que vous
-- avez déjà déposé dans Storage — le lien avec le PDF se fera directement
-- avec le script 14_lier_documents_stockage.sql, sans rien refaire.
-- À coller dans Supabase > SQL Editor > New query > Run
-- ======================================================================

with nouveaux_imports as (
  insert into imports (exercice_id, type_import, mois, nom_fichier, statut)
  select e.id, 'banque', v.mois, v.nom_fichier, 'importé'
  from (values
  ('2023-01', '01.2023.pdf'),
  ('2023-02', '02.2023.pdf'),
  ('2023-03', '03.2023.pdf'),
  ('2023-04', '04.2023.pdf'),
  ('2023-05', '05.2023.pdf'),
  ('2023-06', '06.2023.pdf'),
  ('2023-07', '07.2023.pdf'),
  ('2023-08', '08.2023.pdf'),
  ('2023-09', '09.2023.pdf'),
  ('2023-10', '10.2023.pdf'),
  ('2023-11', '11.2023.pdf'),
  ('2023-12', '12.2023.pdf')
  ) as v(mois, nom_fichier)
  join exercices e on to_date(v.mois || '-01', 'YYYY-MM-DD') between e.date_debut and e.date_fin
  returning id, mois
)
insert into operations_bancaires (
  exercice_id, import_id, date_operation, libelle, debit, credit, affectation, etat
)
select
  e.id, imp.id, v.date_operation::date, v.libelle, v.debit, v.credit, 'COMMUN', 'a_categoriser'
